import {
  createClient,
  defineRequest,
  pickFirstBalancer,
  struct,
  withEndpoint,
  withBalancer,
  withRetry,
} from "@defjs/core";

const getOrder = defineRequest({
  method: "GET",
  path: "/orders/:id",
  input: struct.object({ id: struct.number() }),
  builder: (input) => ({ path: input }),
  output: struct.object({ id: struct.number(), status: struct.string() }),
});
const client = createClient(
  withEndpoint("https://api-us.example.com", "https://api-eu.example.com"),
  withBalancer(pickFirstBalancer({ failbackMs: 30_000 })),
  withRetry({
    maxRetries: 2,
    attemptTimeoutMs: 2_000,
    delayMs: 500,
    maxDelayMs: 5_000,
    // The default retries a connection failure, a 429, 502, 503, or 504, and a timeout.
    // This policy also retries a 408 Request Timeout and leaves every other decision to the default.
    shouldRetry: (context) =>
      context.retryable ||
      (context.transport === "http" && context.status === 408),
    budget: {
      percentCanRetry: 0.2,
      minRetriesPerSecond: 10,
      ttlMs: 10_000,
    },
  }),
);
async function main() {
  const [err, order] = await getOrder(
    client({ signal: AbortSignal.timeout(5_000) }),
    { id: 1 },
  );
  if (err) {
    console.error(err.code);
    return;
  }
  console.log(order.status);
}
void main();

