import type { Attributes } from "@opentelemetry/api";

const http = {
  startSpanHook(request: HttpRequest): Attributes {
    if (!request.baseEndpoint) return {};
    const url = createResolvedRequestUrl(
      request.baseEndpoint,
      request.endpoint,
      request.query?.toString(),
